import itertools
E=('token_embd.weight',200,100); H=('output.weight',100,100); W=('blk.0.attn_q.weight',50,100); N=('blk.0.attn_norm.weight',20,10)
def calc(ts,new):
 s=n=h=hn=0
 for name,b,e in ts:
  if (name=='token_embd.weight' and h==0) or name=='output.weight': h=b*8/e; hn=e
  elif name.endswith('.weight') and (not new or (name!='token_embd.weight' and not name.endswith('norm.weight'))): s+=b*8;n+=e
 return s/n,h,hn*h+s
for ts in [(E,H,W,N),(H,E,W,N),(E,W,N)]:print([x[0] for x in ts],calc(ts,False),calc(ts,True))
print('new results across 24 permutations:',set(calc(p,True) for p in itertools.permutations([E,H,W,N])))

